import { readFile, writeFile } from "node:fs/promises";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const sourceDir = join(root, "assets", "js");

const modules = [
  { key: "api", file: "api.js", exports: ["api", "setCsrf", "getCsrf", "ensureCsrf"] },
  { key: "storage", file: "storage.js", deps: { api: ["api", "setCsrf", "ensureCsrf"] }, exports: ["loadCatalog", "getSettings", "getContent", "getFooterLinks", "getCart", "saveCart", "addToCart", "updateCart", "clearCart", "cartCount", "submitQuote", "submitContact", "CART_KEY"] },
  { key: "art", file: "art.js", exports: ["productArt", "heroArt", "iconFallback"] },
  { key: "ui", file: "ui.js", deps: { storage: ["cartCount", "addToCart", "getSettings", "getFooterLinks"], art: ["productArt", "heroArt", "iconFallback"] }, exports: ["qs", "qsa", "escapeHTML", "money", "icon", "initIcons", "logo", "header", "footer", "shell", "priceMarkup", "productCard", "categoryArt", "breadcrumb", "emptyState", "toast", "updateCartBadge", "bindGlobalUI", "openModal", "productArt", "heroArt"] },
  { key: "pages", file: "pages.js", deps: { storage: ["loadCatalog", "getCart", "updateCart", "clearCart", "getContent", "getSettings", "submitQuote", "submitContact"], ui: ["shell", "heroArt", "productArt", "productCard", "categoryArt", "breadcrumb", "priceMarkup", "money", "escapeHTML", "icon", "qs", "qsa", "bindGlobalUI", "initIcons", "toast", "updateCartBadge", "emptyState"] }, exports: ["homePage", "categoryPage", "productPage", "searchPage", "cartPage", "quotePage", "confirmationPage", "brandsPage", "aboutPage", "contactPage", "renderPublic"] },
  { key: "admin", file: "admin.js", deps: { api: ["api", "setCsrf"], ui: ["logo", "icon", "productArt", "money", "escapeHTML", "qs", "qsa", "initIcons", "toast", "openModal"] }, exports: ["renderAdmin"] },
];

function stripModuleSyntax(source) {
  return source
    .replace(/^import\s+.+?;\s*$/gm, "")
    .replace(/^export\s*\{[^}]+\};?\s*$/gm, "")
    .replace(/\bexport\s+(?=(?:async\s+)?function\b|const\b|let\b|var\b|class\b)/g, "");
}

const output = ["/* Generated by scripts/build-bundle.mjs. Do not edit directly. */"];
for (const module of modules) {
  const source = stripModuleSyntax(await readFile(join(sourceDir, module.file), "utf8"));
  const dependencies = Object.entries(module.deps || {}).map(([key, names]) => `const { ${names.join(", ")} } = __${key};`).join("\n");
  output.push(`const __${module.key} = (() => {\n${dependencies}\n${source}\nreturn { ${module.exports.join(", ")} };\n})();`);
}

let main = stripModuleSyntax(await readFile(join(sourceDir, "main.js"), "utf8"));
main = `const { renderPublic } = __pages;\nconst { renderAdmin } = __admin;\n${main}`;
output.push(`(async () => {\n${main}\n})();`);

await writeFile(join(sourceDir, "app.bundle.js"), output.join("\n\n"), "utf8");
